import { createElement, forwardRef, type SVGProps } from "react";

export type IconNode = [tag: string, attrs: Record<string, string | number>][];

export type LucideProps = Omit<SVGProps<SVGSVGElement>, "ref"> & {
  size?: string | number;
  absoluteStrokeWidth?: boolean;
};

export type LucideIcon = ReturnType<typeof createIcon>;

const defaultAttributes = {
  xmlns: "http://www.w3.org/2000/svg",
  width: 24,
  height: 24,
  viewBox: "0 0 24 24",
  fill: "none",
  stroke: "currentColor",
  strokeWidth: 2,
  strokeLinecap: "round",
  strokeLinejoin: "round",
} as const;

const hasA11yProp = (props: Record<string, unknown>) => {
  for (const prop in props) {
    if (prop.startsWith("aria-") || prop === "role" || prop === "title") return true;
  }
  return false;
};

const mergeClasses = (...classes: (string | undefined)[]) =>
  classes
    .filter((c, i, arr) => Boolean(c) && c!.trim() !== "" && arr.indexOf(c) === i)
    .join(" ")
    .trim();

/** `classes` is the precomputed `lucide-<name>` pair createLucideIcon builds at runtime. */
export function createIcon(displayName: string, classes: string, iconNode: IconNode) {
  const Component = forwardRef<SVGSVGElement, LucideProps>(
    (
      {
        color = "currentColor",
        size = 24,
        strokeWidth = 2,
        absoluteStrokeWidth,
        className = "",
        children,
        ...rest
      },
      ref,
    ) =>
      createElement(
        "svg",
        {
          ref,
          ...defaultAttributes,
          width: size,
          height: size,
          stroke: color,
          strokeWidth: absoluteStrokeWidth
            ? (Number(strokeWidth) * 24) / Number(size)
            : strokeWidth,
          // Two merges, like upstream: createLucideIcon merges its classes with the caller's,
          // then Icon merges "lucide" with that string (so className="lucide" renders twice).
          className: mergeClasses("lucide", mergeClasses(...classes.split(" "), className)),
          ...(!children && !hasA11yProp(rest) && { "aria-hidden": "true" }),
          ...rest,
        },
        ...iconNode.map(([tag, attrs]) => createElement(tag, attrs)),
        ...(Array.isArray(children) ? children : [children]),
      ),
  );
  Component.displayName = displayName;
  return Component;
}
